//! The App Store catalog index (`catalog.json`, generated by `hinteros-catalog`'s
//! `lib.mkIndex`, schema `hinteros-catalog/schema/index.schema.json`, index versions 2 and 3).
//!
//! Version 3 (catalog format 3, M7) renamed version 2's `kind` (`native`/`web`) to `type` and
//! uses `kind` for the entry kind (`app`/`service`); it adds `box` (box features, replacing
//! `requires`), `starter` and `needsServices`. Both versions are read into the same [`Entry`]:
//! `kind` keeps the app type and [`Entry::entry_kind`] holds the entry kind (always `app` for
//! version 2).
//!
//! The running generation installs it at `/run/current-system/sw/share/hinteros/catalog.json`
//! (with the vendor terms next to it under `terms/`). Both daemons read it: the system service
//! checks `apps.install`/`apps.remove` ids against it, the session daemon serves it to the
//! launcher as `store.list`. Receivers ignore unknown fields; an unknown `indexVersion` is
//! refused, like an API major.
//!
//! The index is trusted data (it comes from the signed system revision), but it is still parsed
//! strictly where it reaches root: ids and data paths are checked again here.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use serde::{Deserialize, Serialize};

/// The newest index version this code understands.
pub const INDEX_VERSION: u32 = 3;

/// Index versions this code reads.
pub const INDEX_VERSIONS: &[u32] = &[2, 3];

/// Box features an app may need (catalog format 3, apps.md "Box requirements").
pub const BOX_FEATURES: &[&str] = &["graphics32", "steam-devices"];

pub fn is_box_feature(s: &str) -> bool {
    BOX_FEATURES.contains(&s)
}

/// Sandbox permissions an app may declare (`permissions`, optional in format 3), in the order
/// they are shown. Other names are ignored (not enforced, so not listed).
pub const PERMISSIONS: &[&str] = &["gamepad", "mic", "downloads"];

/// Whether an app needs a permission (`permissions` values).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Need {
    Required,
    Optional,
    /// A value this code does not know: treated like `required` (it cannot be switched off).
    #[serde(other)]
    Unknown,
}

impl Need {
    pub fn required(self) -> bool {
        self != Need::Optional
    }
}

/// What an entry is (format 3): an app (per profile, in the Store) or a box-wide service.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EntryKind {
    #[default]
    App,
    Service,
    /// A kind this code does not know: ignored like a service (never installable as an app).
    #[serde(other)]
    Unknown,
}

/// Default location of the running generation's index.
pub const DEFAULT_INDEX: &str = "/run/current-system/sw/share/hinteros/catalog.json";

/// Most apps one `apps.install` / `apps.remove` may name.
pub const MAX_IDS: usize = 8;

/// `^[a-z0-9][a-z0-9-]{0,31}$` (catalog ids, also what `state.json`'s `apps` stores).
pub fn is_app_id(s: &str) -> bool {
    let b = s.as_bytes();
    !b.is_empty()
        && b.len() <= 32
        && (b[0].is_ascii_lowercase() || b[0].is_ascii_digit())
        && b.iter()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == b'-')
}

/// A terms version: `^[A-Za-z0-9._-]{1,32}$`.
pub fn is_terms_version(s: &str) -> bool {
    (1..=32).contains(&s.len())
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'_' | b'-'))
}

/// A `dataPaths` entry: relative to a home, 1 to 200 bytes, no leading `/` or `~`, no empty,
/// `.` or `..` components, no wildcards, no control characters.
pub fn is_data_path(s: &str) -> bool {
    !s.is_empty()
        && s.len() <= 200
        && !s.starts_with('/')
        && !s.starts_with('~')
        && !s.ends_with('/')
        && !s
            .chars()
            .any(|c| c.is_control() || matches!(c, '*' | '?' | '[' | ']' | '\\'))
        && s.split('/').all(|c| !c.is_empty() && c != "." && c != "..")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Status {
    Available,
    Retired,
    Removed,
    /// A status this code does not know: treated like `retired` (keeps working, not
    /// installable).
    #[serde(other)]
    Unknown,
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Icon {
    pub desktop_id: Option<String>,
    pub site_url: Option<String>,
    pub icon_url: Option<String>,
    #[serde(default)]
    pub firefox_profile: bool,
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct Terms {
    pub title: String,
    pub version: String,
    pub url: String,
    pub retrieved: String,
    /// `terms/<name>.txt`, relative to the index file.
    pub file: String,
}

/// One entry. Tombstones (`status: removed`) only have `id`, `name`, `status` and
/// `statusReason`; everything else then has its default.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Entry {
    pub id: String,
    pub name: String,
    #[serde(default)]
    pub summary: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub category: String,
    #[serde(default)]
    pub homepage: String,
    /// The app type: `native`, `web` (`service` for services). Version 2's `kind`, version
    /// 3's `type`.
    #[serde(default)]
    pub kind: String,
    /// Version 3's `type` (moved into `kind` by [`Index::parse`]).
    #[serde(default, rename = "type")]
    type_: Option<String>,
    /// The entry kind (version 3's `kind`; `app` for version 2).
    #[serde(skip)]
    pub entry_kind: EntryKind,
    /// Box features the app needs (version 3; version 2's `requires`).
    #[serde(default, rename = "box")]
    pub box_features: Vec<String>,
    /// Installer app step (version 3): `offered`, `ticked` or none.
    #[serde(default)]
    pub starter: Option<String>,
    /// Services the app needs (version 3).
    #[serde(default)]
    pub needs_services: Vec<String>,
    #[serde(default, rename = "sizeMiB")]
    pub size_mib: u64,
    #[serde(default)]
    pub icon: Icon,
    #[serde(default)]
    pub requires: Vec<String>,
    #[serde(default)]
    pub depends: Vec<String>,
    #[serde(default)]
    pub conflicts: Vec<String>,
    #[serde(default)]
    pub installer: bool,
    #[serde(default)]
    pub on_iso: bool,
    #[serde(default)]
    pub installer_default: bool,
    #[serde(default)]
    pub data_paths: Vec<String>,
    #[serde(default)]
    pub terms: Option<Terms>,
    pub status: Status,
    #[serde(default)]
    pub status_reason: Option<String>,
    #[serde(default)]
    pub builds_on_device: bool,
    #[serde(default)]
    pub free: bool,
    #[serde(default)]
    pub redistributable: bool,
    /// Sandbox permissions (name -> need; optional, index version 3).
    #[serde(default)]
    pub permissions: BTreeMap<String, Need>,
    /// `false`: the app runs without the sandbox (optional; default true).
    #[serde(default = "yes")]
    pub sandbox: bool,
}

fn yes() -> bool {
    true
}

#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "camelCase")]
struct RawIndex {
    index_version: u32,
    apps: Vec<Entry>,
}

/// A parsed, checked index.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Index {
    /// The directory of the index file (terms files are relative to it).
    pub dir: PathBuf,
    /// `indexVersion` of the file.
    pub version: u32,
    pub apps: BTreeMap<String, Entry>,
}

#[derive(Debug, thiserror::Error)]
pub enum IndexError {
    #[error("{0} not found")]
    Missing(PathBuf),
    #[error("reading {0}: {1}")]
    Io(PathBuf, std::io::Error),
    #[error("{0} is invalid: {1}")]
    Invalid(PathBuf, String),
    #[error("{path} has index version {found}, this daemon reads versions 2 and 3")]
    Version { path: PathBuf, found: u32 },
}

impl Index {
    pub fn load(path: &Path) -> Result<Self, IndexError> {
        let bytes = match std::fs::read(path) {
            Ok(b) => b,
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                return Err(IndexError::Missing(path.to_owned()));
            }
            Err(e) => return Err(IndexError::Io(path.to_owned(), e)),
        };
        let dir = path.parent().unwrap_or(Path::new("/")).to_owned();
        Self::parse(&bytes, dir).map_err(|e| match e {
            ParseError::Version(found) => IndexError::Version {
                path: path.to_owned(),
                found,
            },
            ParseError::Invalid(m) => IndexError::Invalid(path.to_owned(), m),
        })
    }

    pub fn parse(bytes: &[u8], dir: PathBuf) -> Result<Self, ParseError> {
        // The version first, so a future format is reported as such and not as garbage.
        #[derive(Deserialize)]
        #[serde(rename_all = "camelCase")]
        struct Version {
            index_version: u32,
        }
        let v: Version =
            serde_json::from_slice(bytes).map_err(|e| ParseError::Invalid(e.to_string()))?;
        if !INDEX_VERSIONS.contains(&v.index_version) {
            return Err(ParseError::Version(v.index_version));
        }
        let raw: RawIndex =
            serde_json::from_slice(bytes).map_err(|e| ParseError::Invalid(e.to_string()))?;
        let mut apps = BTreeMap::new();
        for mut e in raw.apps {
            if raw.index_version >= 3 {
                e.entry_kind = match e.kind.as_str() {
                    "app" => EntryKind::App,
                    "service" => EntryKind::Service,
                    _ => EntryKind::Unknown,
                };
                e.kind = e.type_.take().unwrap_or_else(|| "native".into());
            } else {
                e.entry_kind = EntryKind::App;
                if e.box_features.is_empty() {
                    e.box_features = e
                        .requires
                        .iter()
                        .filter(|r| is_box_feature(r))
                        .cloned()
                        .collect();
                }
            }
            check_entry(&e).map_err(ParseError::Invalid)?;
            if apps.insert(e.id.clone(), e).is_some() {
                return Err(ParseError::Invalid("duplicate id".into()));
            }
        }
        Ok(Self {
            dir,
            version: raw.index_version,
            apps,
        })
    }

    pub fn get(&self, id: &str) -> Option<&Entry> {
        self.apps.get(id)
    }

    /// An app entry that is not a tombstone (not a service either).
    pub fn app(&self, id: &str) -> Option<&Entry> {
        self.get(id)
            .filter(|e| e.entry_kind == EntryKind::App && e.status != Status::Removed)
    }

    /// The box features `ids` need (sorted, unique; unknown ids and services count nothing).
    pub fn box_features<'a>(&self, ids: impl IntoIterator<Item = &'a String>) -> Vec<String> {
        let set: BTreeSet<String> = ids
            .into_iter()
            .filter_map(|id| self.app(id))
            .flat_map(|e| e.box_features.iter().cloned())
            .collect();
        set.into_iter().collect()
    }

    /// The absolute path of an entry's terms text (checked to stay in `terms/`).
    pub fn terms_file(&self, terms: &Terms) -> PathBuf {
        self.dir.join(&terms.file)
    }

    /// Every app `ids` needs, `ids` first, then their dependencies (transitively), each once.
    /// `Err(id)`: an id (or a dependency) that is not in the index.
    pub fn with_dependencies(&self, ids: &[String]) -> Result<Vec<String>, String> {
        let mut out: Vec<String> = Vec::new();
        let mut seen = BTreeSet::new();
        let mut queue: std::collections::VecDeque<String> = ids.iter().cloned().collect();
        while let Some(id) = queue.pop_front() {
            if !seen.insert(id.clone()) {
                continue;
            }
            let entry = self.get(&id).ok_or_else(|| id.clone())?;
            out.push(id);
            queue.extend(entry.depends.iter().cloned());
        }
        Ok(out)
    }
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ParseError {
    #[error("unsupported index version {0}")]
    Version(u32),
    #[error("{0}")]
    Invalid(String),
}

fn check_entry(e: &Entry) -> Result<(), String> {
    if !is_app_id(&e.id) {
        return Err(format!("bad id {:?}", e.id));
    }
    for f in &e.box_features {
        if !is_box_feature(f) {
            return Err(format!("{}: unknown box feature {f:?}", e.id));
        }
    }
    for d in e
        .depends
        .iter()
        .chain(&e.conflicts)
        .chain(&e.needs_services)
    {
        if !is_app_id(d) {
            return Err(format!("{}: bad id {d:?} in depends/conflicts", e.id));
        }
    }
    for p in &e.data_paths {
        if !is_data_path(p) {
            return Err(format!("{}: bad data path {p:?}", e.id));
        }
    }
    if let Some(t) = &e.terms {
        let name_ok = t.file.strip_prefix("terms/").is_some_and(|n| {
            n.ends_with(".txt")
                && n.len() > 4
                && n.bytes()
                    .all(|b| b.is_ascii_alphanumeric() || matches!(b, b'.' | b'_' | b'-'))
                && !n.starts_with('.')
        });
        if !name_ok || !is_terms_version(&t.version) {
            return Err(format!("{}: bad terms", e.id));
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    pub const SAMPLE: &str = r#"{
      "indexVersion": 2,
      "apps": [
        { "id": "steam", "name": "Steam", "summary": "s", "description": "d", "category": "games",
          "homepage": "https://store.steampowered.com", "kind": "native", "sizeMiB": 1000,
          "icon": { "desktopId": "steam", "siteUrl": "https://store.steampowered.com" },
          "requires": ["graphics32"], "depends": [], "conflicts": [], "installer": true,
          "onIso": false, "installerDefault": false, "dataPaths": [".local/share/Steam", ".steam"],
          "terms": { "title": "Steam Subscriber Agreement", "version": "2026-09-10",
                     "url": "https://store.steampowered.com/subscriber_agreement/",
                     "retrieved": "2026-10-06", "file": "terms/steam-2026-09-10.txt" },
          "status": "available", "statusReason": null, "buildsOnDevice": false, "free": false,
          "redistributable": true, "futureField": 1 },
        { "id": "old-app", "name": "Old app", "status": "removed", "statusReason": "gone" }
      ]
    }"#;

    #[test]
    fn parses_index_version_2() {
        let i = Index::parse(SAMPLE.as_bytes(), "/idx".into()).unwrap();
        let s = i.get("steam").unwrap();
        assert_eq!(s.size_mib, 1000);
        assert_eq!(s.icon.desktop_id.as_deref(), Some("steam"));
        assert_eq!(s.data_paths, [".local/share/Steam", ".steam"]);
        assert_eq!(
            i.terms_file(s.terms.as_ref().unwrap()),
            Path::new("/idx/terms/steam-2026-09-10.txt")
        );
        assert_eq!(i.get("old-app").unwrap().status, Status::Removed);
        assert!(i.get("old-app").unwrap().data_paths.is_empty());
    }

    #[test]
    fn refuses_other_versions_and_bad_entries() {
        assert_eq!(
            Index::parse(br#"{"indexVersion":4,"apps":[]}"#, "/".into()).unwrap_err(),
            ParseError::Version(4)
        );
        assert!(
            Index::parse(
                br#"{"indexVersion":3,"apps":[{"id":"a","kind":"app","type":"native","name":"x","status":"available","box":["x86"]}]}"#,
                "/".into()
            )
            .is_err()
        );
        for bad in [
            r#"{"indexVersion":2,"apps":[{"id":"../x","name":"x","status":"available"}]}"#,
            r#"{"indexVersion":2,"apps":[{"id":"a","name":"x","status":"available","dataPaths":["../../etc"]}]}"#,
            r#"{"indexVersion":2,"apps":[{"id":"a","name":"x","status":"available","dataPaths":["/etc"]}]}"#,
            r#"{"indexVersion":2,"apps":[{"id":"a","name":"x","status":"available","depends":["A"]}]}"#,
            r#"{"indexVersion":2,"apps":[{"id":"a","name":"x","status":"available","terms":{"title":"t","version":"1","url":"u","retrieved":"r","file":"../x.txt"}}]}"#,
            r#"{"indexVersion":2,"apps":[{"id":"a","name":"x","status":"available"},{"id":"a","name":"y","status":"available"}]}"#,
            r#"{"apps":[]}"#,
        ] {
            assert!(
                Index::parse(bad.as_bytes(), "/".into()).is_err(),
                "accepted {bad}"
            );
        }
        let i = Index::parse(
            br#"{"indexVersion":2,"apps":[{"id":"a","name":"x","status":"later"}]}"#,
            "/".into(),
        )
        .unwrap();
        assert_eq!(i.get("a").unwrap().status, Status::Unknown);
    }

    #[test]
    fn parses_index_version_3() {
        let i = Index::parse(
            br#"{"indexVersion":3,"apps":[
              {"id":"steam","kind":"app","type":"native","name":"Steam","status":"available",
               "box":["graphics32","steam-devices"],"starter":"offered","needsServices":[]},
              {"id":"jellyfin-server","kind":"service","type":"service","name":"Jellyfin server",
               "status":"available","box":[]},
              {"id":"youtube","kind":"app","type":"web","name":"YouTube","status":"available",
               "starter":"ticked"},
              {"id":"gone","kind":"app","name":"Gone","status":"removed","statusReason":"x"}]}"#,
            "/".into(),
        )
        .unwrap();
        assert_eq!(i.version, 3);
        let s = i.get("steam").unwrap();
        assert_eq!(s.kind, "native");
        assert_eq!(s.entry_kind, EntryKind::App);
        assert_eq!(s.box_features, ["graphics32", "steam-devices"]);
        assert_eq!(s.starter.as_deref(), Some("offered"));
        assert_eq!(i.get("youtube").unwrap().kind, "web");
        assert_eq!(
            i.get("jellyfin-server").unwrap().entry_kind,
            EntryKind::Service
        );
        assert!(i.app("jellyfin-server").is_none() && i.app("gone").is_none());
        let ids: Vec<String> = ["youtube", "steam", "jellyfin-server", "nope"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        assert_eq!(i.box_features(&ids), ["graphics32", "steam-devices"]);
        // Version 2's requires count as box features.
        let v2 = Index::parse(SAMPLE.as_bytes(), "/".into()).unwrap();
        assert_eq!(v2.get("steam").unwrap().box_features, ["graphics32"]);
        assert_eq!(v2.get("steam").unwrap().entry_kind, EntryKind::App);
        // Permissions and sandbox are optional.
        assert!(s.permissions.is_empty() && s.sandbox);
        let p = Index::parse(
            br#"{"indexVersion":3,"apps":[
              {"id":"a","kind":"app","type":"web","name":"A","status":"available",
               "permissions":{"gamepad":"required","mic":"optional","x":"later"},"sandbox":false}]}"#,
            "/".into(),
        )
        .unwrap();
        let a = p.get("a").unwrap();
        assert!(!a.sandbox);
        assert_eq!(a.permissions["gamepad"], Need::Required);
        assert_eq!(a.permissions["mic"], Need::Optional);
        assert!(a.permissions["x"].required());
        assert!(!Need::Optional.required());
    }

    #[test]
    fn data_paths() {
        for ok in [".steam", ".local/share/Steam", ".config/Plex HTPC", "a/b/c"] {
            assert!(is_data_path(ok), "{ok}");
        }
        for bad in [
            "", "/", "/etc", "~/x", "a/../b", "./a", "a/./b", "a//b", "a/", "..", "*", "a/*",
            "a\nb", "a\\b",
        ] {
            assert!(!is_data_path(bad), "{bad:?}");
        }
    }

    #[test]
    fn dependencies_are_transitive_and_unique() {
        let i = Index::parse(
            br#"{"indexVersion":2,"apps":[
              {"id":"a","name":"a","status":"available","depends":["b","c"]},
              {"id":"b","name":"b","status":"available","depends":["c"]},
              {"id":"c","name":"c","status":"available","depends":["a"]},
              {"id":"d","name":"d","status":"available","depends":["zz"]}]}"#,
            "/".into(),
        )
        .unwrap();
        assert_eq!(i.with_dependencies(&["a".into()]).unwrap(), ["a", "b", "c"]);
        assert_eq!(i.with_dependencies(&["d".into()]).unwrap_err(), "zz");
        assert_eq!(i.with_dependencies(&["nope".into()]).unwrap_err(), "nope");
    }
}
